// QueryUserBetHistory 查询用户历史投注（时间倒序）
func (d betRecordsDao) QueryUserBetHistory(
	ctx context.Context,
	siteId uint,
	siteCode string,
	userId uint,
	startTime string,
	endTime string,
	page int,
	size int,
) (list []UserBetHistoryRow, total int, err error) {
	model := d.Ctx(ctx).
		As("br").
		LeftJoin("game_list gl", "gl.site_id = br.site_id AND gl.code = br.game_name").
		Where("br.site_id = ?", siteId).
		Where("br.site_code = ?", siteCode).
		Where("br.user_id = ?", userId).
		Where("br.bet_time >= ?", startTime).
		Where("br.bet_time <= ?", endTime)

	count, err := model.Count()
	if err != nil {
		return nil, 0, err
	}

	offset := (page - 1) * size
	if offset < 0 {
		offset = 0
	}

	err = model.
		Fields(
			"COALESCE(gl.name, br.game_name) AS game_name",
			"br.valid_amount",
			"DATE_FORMAT(br.bet_time, '%Y-%m-%d %H:%i:%s') AS bet_time",
			"br.win_amount",
			"br.net_amount",
			"br.status",
			"br.order_no",
		).
		OrderDesc("br.bet_time").
		Limit(size).
		Offset(offset).
		Scan(&list)
	if err != nil {
		return nil, 0, err
	}

	return list, count, nil
}

